#define BUILD_FINAL
#define NGL
#define TARGET_PS2
#define START_PROF_TIMER(a) {}
#define STOP_PROF_TIMER(a) {}

typedef float time_value_t;
typedef unsigned int uint32;
typedef unsigned long long uint64;

inline uint32 get_cpu_cycle()
{
  register int result;
  __asm__ volatile ("mfc0 %0,$9" : "=r" (result));
  return result;
}

template<class T> class singleton_ptr
{
  T* p;
public:
  operator T*() const { return p; }
};

class master_clock
{
  union {
    uint64 total;
    struct { uint32 lower, upper; } half;
  } ticks;
public:
  uint64 elapsed()
  {
    uint32 curticks = get_cpu_cycle();
    if (curticks < ticks.half.lower)
      ++ticks.half.upper;
    ticks.half.lower = curticks;
    return ticks.total;
  }
  static singleton_ptr<master_clock> instance;
  static master_clock* inst() { return instance; }
};

extern bool g_master_clock_is_up;
extern const float SECONDS_PER_TICK;

class hires_clock_t
{
  uint64 last_reset_ticks;
public:
  void reset() { last_reset_ticks = master_clock::inst()->elapsed(); }
  hires_clock_t()
  {
    if (g_master_clock_is_up == true)
      reset();
    else
      last_reset_ticks = 0;
  }
  time_value_t elapsed() const
  {
    int ticks = master_clock::inst()->elapsed() - last_reset_ticks;
    return (float)ticks * SECONDS_PER_TICK;
  }
};

class signal_manager
{
public:
  static singleton_ptr<signal_manager> instance;
  static signal_manager* inst() { return instance; }
  void do_refresh();
};

class input_mgr
{
public:
  static singleton_ptr<input_mgr> instance;
  static input_mgr* inst() { return instance; }
  void poll_devices();
};

class game
{
  char pad[0x1e8];
  float total_delta;
  char pad2[4];
  float limit_delta;
public:
  void frame_advance();
  void render_shadows();
  void render();
  void set_total_delta(time_value_t new_delta) { total_delta = new_delta; }
  void set_limit_delta(time_value_t new_delta) { limit_delta = new_delta; }
};

class KSReplay
{
public:
  bool IsPlaying();
  bool NoDraw();
};

class FEManager
{
  char pad[0xe678];
public:
  bool fe_done;
};

class MenuRender { public: void Draw(); };

extern KSReplay ksreplay;
extern FEManager frontendmanager;
extern MenuRender* menus;
extern bool doshadowdrawing;
extern float TIMER_GetTotalSec();
extern void nglListInit();
extern void nglSetAnimTime(float);
extern void nglListSend(bool);

class app
{
  char pad[0x10];
  game* the_game;
public:
  void tick();
};

void app::tick()
{
	#ifndef BUILD_FINAL
	if ( dump_heap )
	{
		dump_heap=false;
		mem_dump_heap();
	}
	if ( check_heap )
	{
		//check_heap=false;
		mem_check_heap();
	}
	if ( allocate_way_too_much_memory )
	{
		allocate_way_too_much_memory=false;
		//void *memoryerror=
		malloc(256*1024*1024);
	}
	if ( intentionalstackoverflow )
	{
		intentionalstackoverflow=false;
		overflow_the_stack(2000);
	}
	mem_check_stack_collisions();
	#endif


	START_PROF_TIMER( proftimer_cpu_net );
	// total game frame timer
	hires_clock_t total_timer;
	total_timer.reset();

#if 0 //defined(MEMTRACK)
	mem_check_heap();
#endif

#if defined(TARGET_PC)
	if( !IsWindow(windows_app::inst()->get_hwnd()) )
		return;
#endif

	signal_manager::inst()->do_refresh();  // this must be done once per game frame
	input_mgr::inst()->poll_devices();

#ifdef GCCULL
	START_PROF_TIMER( proftimer_streams );
	sound_stream::advance_queue_requests();
	STOP_PROF_TIMER( proftimer_streams );
#endif

	// Frame Advance (animate) the scene
	START_PROF_TIMER( proftimer_advance );
	the_game->frame_advance();
	STOP_PROF_TIMER( proftimer_advance );

#ifndef BUILD_FINAL
	if ( check_heap )
	{
		//check_heap=false;
		mem_check_heap();
	}
#endif

	// Do not render the scene if replay is advancing to the end
	if(!ksreplay.IsPlaying() || !ksreplay.NoDraw())
	{

		START_PROF_TIMER( proftimer_render );
		START_PROF_TIMER( proftimer_render_cpu );



		// Render the level.
#ifdef NGL
		nglListInit();
			// Render shadows.
		if (doshadowdrawing)
			the_game->render_shadows();
		if (frontendmanager.fe_done)
			nglSetAnimTime (TIMER_GetTotalSec());
#else
		material::flush_last_context();
		fog_manager::inst()->update_fog();
		hw_rasta::inst()->begin_scene();
#endif
		menus->Draw();



		the_game->render();

		// The flip is now performed inside nglListSend, between building and sending the DMA chain. (dc 10/15/01)
		START_PROF_TIMER( proftimer_render_sendlist );
		// Don't flip the first time, because the back buffer is still uninitialized (dc 04/27/02)
		static bool first_time_ever = true;
#ifdef TARGET_PS2
		nglListSend(true);
#else
		nglListSend(!first_time_ever);
#endif
		first_time_ever = false;
		STOP_PROF_TIMER( proftimer_render_sendlist );

		STOP_PROF_TIMER( proftimer_render_cpu );
		STOP_PROF_TIMER( proftimer_render );
	}

	// total game frame time
	the_game->set_total_delta(total_timer.elapsed());
	the_game->set_limit_delta(0.0f);
	STOP_PROF_TIMER( proftimer_cpu_net );

#if defined(TARGET_XBOX) && !defined(BUILD_FINAL)
	if (
		input_mgr::inst()->get_control_state(ANY_LOCAL_JOYSTICK, PSX_SELECT) == AXIS_MAX &&
		input_mgr::inst()->get_control_state(ANY_LOCAL_JOYSTICK, PSX_START) == AXIS_MAX &&
		g_game_ptr != NULL
	   )
	{
		// Reboot to the dashboard.  Useful for people testing the game outside DevStudio.
		// Button combination is same as in XDK samples.  (dc 04/17/02)
		reboot_timer += g_game_ptr->get_total_delta();
		if(reboot_timer >= 3.0f)
			XLaunchNewImage(NULL, NULL);
	}
	else
		reboot_timer = 0.0f;
#endif
}
